-- Учётные записи admin и dev заводит миграция V19 — со своими
-- идентификаторами. В наборе разработки они тоже есть, но с другими,
-- и на них ссылаются доступы и документы. Поэтому сначала убираем
-- одноимённую запись с ЧУЖИМ идентификатором, а потом вставляем свою.
--
-- При повторном запуске удалять нечего: идентификатор уже наш,
-- условие не срабатывает. Если же на чужую запись успели сослаться
-- документы, удаление упадёт — и это правильно: молча подменять
-- автора документов нельзя.
DELETE FROM dbo.app_user WHERE login = 'client@roga-kopyta.kz' AND user_id <> '39173018-3f4e-4f2e-88e3-e989e4b7a9ce';
DELETE FROM dbo.app_user WHERE login = 'warehouse@ahlers.com' AND user_id <> '84062747-661c-446f-aaf7-d6efa18e59bd';
DELETE FROM dbo.app_user WHERE login = 'admin@ahlers.com' AND user_id <> '712c56d8-9075-4289-a455-29b8b4756060';
