-- ---------------------------------------------------------------------
-- Счётчики — вровень с данными
-- ---------------------------------------------------------------------
-- Ключи этих таблиц портал выдаёт счётчиком, а здесь они вставлены
-- готовыми значениями. Явная вставка счётчик не двигает: он остаётся
-- на единице, и первая же запись из портала упала бы на «такой ключ
-- уже есть». Поэтому после загрузки догоняем каждый счётчик.
--
-- Третий аргумент setval равен false — это значит «следующее значение
-- будет ровно таким». Для пустой таблицы получится 1, как и должно.
DO $seq$
DECLARE
  r record;
  v_max bigint;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('user_depositor_access', 'id'),
      ('user_warehouse_access', 'id'),
      ('registered_service',    'id'),
      ('service_tariff',        'id'),
      ('invoice',               'id')) AS t(tbl, col)
  LOOP
    EXECUTE format('SELECT coalesce(max(%I), 0) FROM dbo.%I', r.col, r.tbl) INTO v_max;
    PERFORM setval(pg_get_serial_sequence('dbo.' || r.tbl, r.col), v_max + 1, false);
  END LOOP;
END
$seq$;

SET session_replication_role = origin;

COMMIT;
